begin;
insert into clinic_finance.accounts values('2150','مقدمات حجوزات المرضى','liability') on conflict do nothing;
create table clinic_finance.advances(id uuid primary key default gen_random_uuid(),booking_id uuid references public.customer_bookings(id),patient_ref text not null,amount numeric(14,2) not null check(amount>0),method text not null check(method in ('cash','pos','bank','wallet')),shift_id uuid references clinic_finance.shifts(id),reference text not null,payload jsonb not null,created_by uuid not null references public.admins(id),token uuid not null,created_at timestamptz not null default now(),status text not null check(status in ('pending','received','rejected')),verified_by uuid references public.admins(id),verification_note text,unique(method,reference),unique(created_by,token));
create table clinic_finance.advance_uses(id uuid primary key default gen_random_uuid(),advance_id uuid not null references clinic_finance.advances(id),kind text not null check(kind in ('allocate','refund')),amount numeric(14,2) not null check(amount>0),invoice_id uuid references clinic_finance.invoices(id),payment_id uuid references clinic_finance.payments(id),shift_id uuid references clinic_finance.shifts(id),reference text not null unique,payload jsonb not null,created_by uuid not null references public.admins(id),token uuid not null,created_at timestamptz not null default now(),status text not null check(status in ('pending','approved','rejected')),reviewed_by uuid references public.admins(id),review_note text,unique(created_by,token));
create table clinic_finance.booking_messages(id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.customer_bookings(id),kind text not null check(kind in ('confirmation','reminder')),version text not null,body text not null,phone text not null,status text not null default 'ready' check(status in ('ready','manual_sent','cancelled')),created_by uuid not null references public.admins(id),created_at timestamptz not null default now(),sent_by uuid references public.admins(id),note text,unique(booking_id,kind,version));
create or replace function clinic_finance.booking_access(p_action text) returns uuid language plpgsql stable security definer set search_path=pg_catalog,public as $$begin if public.my_admin_id() is null or not (clinic_finance.allowed(p_action) or p_action in ('view','create') and public.has_role('reception')) then raise exception 'ليس لديك صلاحية لعمليات خزينة الاستقبال' using errcode='42501';end if;return public.my_admin_id();end $$;
create or replace function clinic_finance.advance_available(p_id uuid,p_except uuid default null) returns numeric language sql stable security definer set search_path=pg_catalog,public as $$select a.amount-coalesce((select sum(amount) from clinic_finance.advance_uses where advance_id=a.id and status in ('pending','approved') and id is distinct from p_except),0) from clinic_finance.advances a where a.id=p_id and a.status='received'$$;
create or replace function public.clinic_booking_shift(p_action text,p_payload jsonb,p_token uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$
declare me uuid:=clinic_finance.booking_access('create');s clinic_finance.shifts%rowtype;v uuid;c record;total numeric:=0;begin perform clinic_finance.lock_day();
if p_action='open' then select * into s from clinic_finance.shifts where cashier_id=me and token=p_token;if found then return s.id;end if;
 insert into clinic_finance.shifts(register_id,cashier_id,token,opening_book) select r.id,me,p_token,coalesce((select sum(l.debit-l.credit) from clinic_finance.lines l join clinic_finance.entries e on e.id=l.entry_id join clinic_finance.shifts sh on sh.id=e.shift_id where sh.register_id=r.id and l.account='1111'),0) from clinic_finance.registers r where r.id=(p_payload->>'register_id')::uuid returning id into v;if v is null then raise exception 'اختر خزينة مسجلة';end if;
elsif p_action='close' then
 v:=(p_payload->>'shift_id')::uuid;perform clinic_finance.check_shift(v);if clinic_finance.has_pending_shift(v) then raise exception 'توجد طلبات معلقة على الوردية';end if;
 if jsonb_typeof(p_payload->'counts') is distinct from 'object' or p_payload->'counts'='{}'::jsonb then raise exception 'أدخل جرد الفئات';end if;
 for c in select key,value from jsonb_each_text(p_payload->'counts') loop if c.key not in ('200','100','50','20','10','5','1','0.5','0.25') or c.value is null or c.value!~'^[0-9]{1,7}$' then raise exception 'الفئات أو أعدادها غير صالحة';end if;total:=total+c.key::numeric*c.value::numeric;end loop;
 update clinic_finance.shifts set counted=total,denominations=p_payload->'counts',note=left(coalesce(p_payload->>'note',''),1000),status='submitted',closed_at=now() where id=v;
else raise exception 'إجراء غير معروف';end if;insert into clinic_finance.audit(actor,action,entity_id) values(me,'reception_shift_'||p_action,v);return v;end $$;
create or replace function public.clinic_booking_command(p_action text,p_payload jsonb,p_token uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$
#variable_conflict use_variable
declare me uuid:=clinic_finance.booking_access('create');v uuid;a clinic_finance.advances%rowtype;u clinic_finance.advance_uses%rowtype;i clinic_finance.invoices%rowtype;b public.customer_bookings%rowtype;msg clinic_finance.booking_messages%rowtype;amount numeric;available numeric;pid uuid;sh uuid;channel text;patient text;legacy boolean:=coalesce((p_payload->>'legacy')::boolean,false);version text;body text;
begin perform clinic_finance.lock_day();
if p_action in ('receive','allocate','refund') then
 amount:=(p_payload->>'amount')::numeric;if amount is null or amount<=0 or amount<>round(amount,2) or amount::text in ('NaN','Infinity','-Infinity') or coalesce(length(trim(p_payload->>'reference')),0)<2 then raise exception 'المبلغ أو المرجع غير صالح';end if;end if;
if p_action='receive' then
 select * into a from clinic_finance.advances where created_by=me and token=p_token;if found then if a.payload<>p_payload then raise exception 'مفتاح مستخدم لبيانات أخرى';end if;return a.id;end if;
 patient:=trim(p_payload->>'patient_ref');if coalesce(length(patient),0)<2 then raise exception 'مرجع المريض مطلوب لربط المقدم بالفاتورة';end if;
 if nullif(p_payload->>'booking_id','') is not null then select * into b from public.customer_bookings where id=(p_payload->>'booking_id')::uuid;if not found or b.status in ('cancelled','no_show') or patient<>b.booking_request_id or coalesce(b.currency,'EGP')<>'EGP' then raise exception 'الحجز أو مرجع المريض أو العملة غير صالح';end if;end if;
 if exists(select 1 from clinic_finance.payments where method=p_payload->>'method' and reference=trim(p_payload->>'reference')) then raise exception 'مرجع التحصيل مسجل على فاتورة بالفعل';end if;
 channel:=p_payload->>'method';if channel is null or channel not in ('cash','pos','bank','wallet') then raise exception 'اختر قناة التحصيل';end if;
 if legacy then perform clinic_finance.require_access('create');if exists(select 1 from clinic_finance.manual_batches where kind='opening' and status='approved') then raise exception 'تم اعتماد الافتتاح؛ لا يمكن إضافة مقدم قديم';end if;
 elsif channel in ('cash','pos') then sh:=(p_payload->>'shift_id')::uuid;perform clinic_finance.check_shift(sh);end if;
 insert into clinic_finance.advances(booking_id,patient_ref,amount,method,shift_id,reference,payload,created_by,token,status) values(b.id,patient,amount,channel,sh,trim(p_payload->>'reference'),p_payload,me,p_token,case when legacy or channel in ('bank','wallet') then 'pending' else 'received' end) returning * into a;v:=a.id;
 if a.status='received' then perform clinic_finance.post('advance_receipt',v,'مقدم حجز '||a.reference,sh,case channel when 'cash' then '1111' else '1114' end,'2150',amount);end if;
elsif p_action='verify' then
 perform clinic_finance.require_access('review');select * into a from clinic_finance.advances where id=(p_payload->>'id')::uuid for update;if not found or a.status<>'pending' or a.created_by=me or coalesce(length(trim(p_payload->>'note')),0)<3 then raise exception 'يلزم مقدم معلق ومراجع آخر ونتيجة التحقق';end if;v:=a.id;
 if (p_payload->>'approve')::boolean then
 legacy:=coalesce((a.payload->>'legacy')::boolean,false);if legacy and exists(select 1 from clinic_finance.manual_batches where kind='opening' and status='approved') then raise exception 'اعتمدت الأرصدة الافتتاحية بالفعل';end if;
 perform clinic_finance.post(case when legacy then 'advance_opening' else 'advance_verified' end,v,'تحقق مقدم '||a.reference,null,case when legacy then '3199' when a.method='bank' then '1112' else '1115' end,'2150',a.amount);end if;
 update clinic_finance.advances set status=case when (p_payload->>'approve')::boolean then 'received' else 'rejected' end,verified_by=me,verification_note=p_payload->>'note' where id=v;
elsif p_action in ('allocate','refund') then
 select * into u from clinic_finance.advance_uses where created_by=me and token=p_token;if found then if u.payload<>p_payload then raise exception 'مفتاح مستخدم لبيانات أخرى';end if;return u.id;end if;
 select * into a from clinic_finance.advances where id=(p_payload->>'advance_id')::uuid for update;if not clinic_finance.allowed('create') and a.created_by is distinct from me then raise exception 'المقدم خارج نطاق الاستقبال الخاص بك';end if;available:=clinic_finance.advance_available(a.id);if available is null or amount>available then raise exception 'المبلغ يتجاوز المقدم المتاح بعد حجز الطلبات المعلقة';end if;
 if p_action='allocate' then
 perform clinic_finance.require_access('create');select * into i from clinic_finance.invoices where id=(p_payload->>'invoice_id')::uuid and not voided and patient_ref=a.patient_ref for update;if not found then raise exception 'الفاتورة ومرجع المريض لا يطابقان صاحب المقدم';end if;
 select i.amount-coalesce((select sum(p.amount) from clinic_finance.payments p where p.invoice_id=i.id),0)-coalesce((select sum(c.amount) from clinic_finance.insurance_claims c where c.invoice_id=i.id),0) into available;if amount>available then raise exception 'المقدم المستخدم يتجاوز المتبقي على المريض';end if;
 insert into clinic_finance.payments(invoice_id,method,amount,reference,created_by,token) values(i.id,a.method,amount,'ADV-ALLOC-'||trim(p_payload->>'reference'),me,gen_random_uuid()) returning id into pid;
 else if a.method='cash' then sh:=(p_payload->>'shift_id')::uuid;perform clinic_finance.check_shift(sh);end if;if coalesce(length(trim(p_payload->>'note')),0)<3 then raise exception 'سبب استرداد المقدم مطلوب';end if;end if;
 insert into clinic_finance.advance_uses(advance_id,kind,amount,invoice_id,payment_id,shift_id,reference,payload,created_by,token,status) values(a.id,p_action,amount,i.id,pid,sh,trim(p_payload->>'reference'),p_payload,me,p_token,case when p_action='allocate' then 'approved' else 'pending' end) returning id into v;
 if p_action='allocate' then perform clinic_finance.post('advance_allocation',v,'استخدام مقدم على فاتورة '||i.reference,null,'2150','1122',amount);perform clinic_finance.doctor_sync(i.id);end if;
elsif p_action='refund_review' then
 perform clinic_finance.require_access('review');select * into u from clinic_finance.advance_uses where id=(p_payload->>'id')::uuid and kind='refund' for update;if not found or u.status<>'pending' or u.created_by=me or coalesce(length(trim(p_payload->>'note')),0)<3 then raise exception 'يلزم استرداد معلق ومراجع آخر ونتيجة الفحص';end if;select * into a from clinic_finance.advances where id=u.advance_id;v:=u.id;
 if (p_payload->>'approve')::boolean then if u.amount>clinic_finance.advance_available(a.id,u.id) then raise exception 'تغير المقدم المتاح';end if;if a.method='cash' then perform clinic_finance.check_shift(u.shift_id,false);end if;perform clinic_finance.post('advance_refund',v,'رد مقدم '||u.reference,u.shift_id,'2150',case a.method when 'cash' then '1111' when 'pos' then '1114' when 'bank' then '1112' else '1115' end,u.amount);end if;
 update clinic_finance.advance_uses set status=case when (p_payload->>'approve')::boolean then 'approved' else 'rejected' end,reviewed_by=me,review_note=p_payload->>'note' where id=v;
elsif p_action='message_prepare' then
 select * into b from public.customer_bookings where id=(p_payload->>'booking_id')::uuid;if not found or b.status not in ('confirmed','rescheduled') or b.appointment_date<(now() at time zone 'Africa/Cairo')::date or nullif(b.phone,'') is null and nullif(b.wa_id,'') is null or coalesce(p_payload->>'kind','') not in ('confirmation','reminder') then raise exception 'الحجز أو نوع الرسالة أو هاتف التواصل غير صالح';end if;
 version:=b.appointment_date::text||' '||coalesce(b.appointment_time,'')||' '||coalesce(b.doctor_id,b.doctor_name,'');body:=case when p_payload->>'kind'='reminder' then 'تذكير بموعدك في عيادات سونو التخصصية: ' else 'تأكيد حجزك في عيادات سونو التخصصية: ' end||coalesce(b.customer_name,'')||'، '||b.appointment_date::text||' '||coalesce(b.appointment_time,'')||'، '||coalesce(b.doctor_name,b.specialty_name,'')||'. مرجع الحجز: '||coalesce(b.booking_reference,b.booking_request_id)||'. للاستفسار: 01010686264';
 insert into clinic_finance.booking_messages(booking_id,kind,version,body,phone,created_by) values(b.id,p_payload->>'kind',version,body,coalesce(nullif(b.phone,''),b.wa_id),me) on conflict on constraint booking_messages_booking_id_kind_version_key do nothing returning id into v;if v is null then select id into v from clinic_finance.booking_messages where booking_id=b.id and kind=p_payload->>'kind' and booking_messages.version=version;end if;
elsif p_action='message_sent' then
 select * into msg from clinic_finance.booking_messages where id=(p_payload->>'id')::uuid for update;if not found or msg.status<>'ready' or coalesce((p_payload->>'confirmed')::boolean,false)=false or coalesce(length(trim(p_payload->>'note')),0)<3 then raise exception 'أكد الإرسال الفعلي وسجل مرجعه';end if;
 select * into b from public.customer_bookings where id=msg.booking_id;if b.status not in ('confirmed','rescheduled') or msg.version<>b.appointment_date::text||' '||coalesce(b.appointment_time,'')||' '||coalesce(b.doctor_id,b.doctor_name,'') then raise exception 'تغير الحجز؛ جهز رسالة جديدة';end if;
 update clinic_finance.booking_messages set status='manual_sent',sent_by=me,note=p_payload->>'note' where id=msg.id;v:=msg.id;
else raise exception 'إجراء غير معروف';end if;
insert into clinic_finance.audit(actor,action,entity_id) values(me,'booking_'||p_action,v);return v;end $$;
create or replace function public.clinic_booking_snapshot(p_from date,p_to date) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare me uuid:=clinic_finance.booking_access('view');begin if p_from is null or p_to is null or p_to<p_from or p_to-p_from>366 then raise exception 'حدد فترة لا تزيد عن سنة';end if;
return jsonb_build_object('me',me,'can_create',clinic_finance.allowed('create') or public.has_role('reception'),'can_allocate',clinic_finance.allowed('create'),'can_review',clinic_finance.allowed('review'),'registers',(select coalesce(jsonb_agg(r),'[]') from(select id,name from clinic_finance.registers)r),'shifts',(select coalesce(jsonb_agg(x),'[]') from(select s.id,s.status,s.counted,s.opened_at,r.name register_name from clinic_finance.shifts s join clinic_finance.registers r on r.id=s.register_id where s.cashier_id=me and s.status<>'reviewed')x),'bookings',(select coalesce(jsonb_agg(x),'[]') from(select id,booking_request_id,booking_reference,customer_name,phone,wa_id,doctor_name,appointment_date,appointment_time,status from public.customer_bookings where appointment_date between p_from and p_to order by appointment_date,appointment_time limit 500)x),'advances',(select coalesce(jsonb_agg(x),'[]') from(select a.*,clinic_finance.advance_available(a.id) available from clinic_finance.advances a where (clinic_finance.allowed('view') or a.created_by=me) and (a.status='pending' or (a.created_at at time zone 'Africa/Cairo')::date between p_from and p_to) order by a.created_at desc limit 500)x),'advance_uses',(select coalesce(jsonb_agg(x),'[]') from(select u.*,a.patient_ref,a.method from clinic_finance.advance_uses u join clinic_finance.advances a on a.id=u.advance_id where (clinic_finance.allowed('view') or u.created_by=me) and (u.status='pending' or (u.created_at at time zone 'Africa/Cairo')::date between p_from and p_to) order by u.created_at desc limit 500)x),'messages',(select coalesce(jsonb_agg(x),'[]') from(select m.*,b.appointment_date,b.status booking_status,(m.version=b.appointment_date::text||' '||coalesce(b.appointment_time,'')||' '||coalesce(b.doctor_id,b.doctor_name,'')) current_version from clinic_finance.booking_messages m join public.customer_bookings b on b.id=m.booking_id where b.appointment_date between p_from and p_to order by m.created_at desc limit 500)x));end $$;
alter function public.clinic_finance_snapshot(date,date,integer) set schema clinic_finance;
alter function clinic_finance.clinic_finance_snapshot(date,date,integer) rename to advance_snapshot_base;
create function public.clinic_finance_snapshot(p_from date,p_to date,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare v jsonb:=clinic_finance.advance_snapshot_base(p_from,p_to,p_offset);begin return v||jsonb_build_object('advance_data',public.clinic_booking_snapshot(p_from,p_to));end $$;

alter function public.clinic_finance_collect(uuid,uuid,text,numeric,text,uuid) set schema clinic_finance;
alter function clinic_finance.clinic_finance_collect(uuid,uuid,text,numeric,text,uuid) rename to advance_collect_base;
create function public.clinic_finance_collect(p_invoice uuid,p_shift uuid,p_method text,p_amount numeric,p_reference text,p_token uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$begin perform clinic_finance.require_access('create');perform clinic_finance.lock_day();if exists(select 1 from clinic_finance.advances where method=p_method and reference=trim(p_reference) and status<>'rejected') then raise exception 'مرجع التحصيل مسجل كمقدم حجز؛ استخدم المقدم على الفاتورة';end if;return clinic_finance.advance_collect_base(p_invoice,p_shift,p_method,p_amount,p_reference,p_token);end $$;
create function clinic_finance.has_pending_shift(p_shift uuid) returns boolean language sql stable security definer set search_path=pg_catalog,public as $$select exists(select 1 from clinic_finance.requests where shift_id=p_shift and status='pending') or exists(select 1 from clinic_finance.advance_uses where shift_id=p_shift and status='pending') or exists(select 1 from clinic_finance.doctor_payouts where shift_id=p_shift and status='pending') or exists(select 1 from clinic_finance.supplier_actions where shift_id=p_shift and status='pending') or exists(select 1 from clinic_finance.business_requests where payload->>'shift_id'=p_shift::text and status='pending')$$;
alter function public.clinic_finance_close_shift(uuid,jsonb,text) set schema clinic_finance;
alter function clinic_finance.clinic_finance_close_shift(uuid,jsonb,text) rename to advance_close_shift_base;
create function public.clinic_finance_close_shift(p_shift uuid,p_counts jsonb,p_note text) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$begin perform clinic_finance.require_access('create');perform clinic_finance.lock_day();if clinic_finance.has_pending_shift(p_shift) then raise exception 'توجد طلبات معلقة على الوردية';end if;return clinic_finance.advance_close_shift_base(p_shift,p_counts,p_note);end $$;
alter function public.clinic_finance_close_period(date) set schema clinic_finance;
alter function clinic_finance.clinic_finance_close_period(date) rename to advance_close_period_base;
create function public.clinic_finance_close_period(p_through date) returns date language plpgsql security definer set search_path=pg_catalog,public as $$begin perform clinic_finance.require_access('review');perform clinic_finance.lock_day();if exists(select 1 from (select created_at,status from clinic_finance.advances union all select created_at,status from clinic_finance.advance_uses union all select created_at,status from clinic_finance.doctor_payouts union all select created_at,status from clinic_finance.doctor_contracts union all select created_at,status from clinic_finance.supplier_actions union all select created_at,status from clinic_finance.business_requests union all select created_at,status from clinic_finance.insurance_actions union all select created_at,status from clinic_finance.manual_batches union all select created_at,status from clinic_finance.pos_settlements)q where status='pending' and (created_at at time zone 'Africa/Cairo')::date<=p_through) or exists(select 1 from clinic_finance.bank_statements where status='pending' and to_date<=p_through) then raise exception 'توجد عمليات مالية أو مطابقات معلقة قبل تاريخ الإقفال';end if;return clinic_finance.advance_close_period_base(p_through);end $$;
revoke all on function public.clinic_finance_collect(uuid,uuid,text,numeric,text,uuid),public.clinic_finance_close_shift(uuid,jsonb,text),public.clinic_finance_close_period(date) from public,anon;
grant execute on function public.clinic_finance_collect(uuid,uuid,text,numeric,text,uuid),public.clinic_finance_close_shift(uuid,jsonb,text),public.clinic_finance_close_period(date) to authenticated;

do $$declare t text;begin foreach t in array array['advances','advance_uses','booking_messages'] loop execute format('alter table clinic_finance.%I enable row level security',t);end loop;end $$;
revoke all on all tables in schema clinic_finance from public,anon,authenticated;
revoke all on all functions in schema clinic_finance from public,anon,authenticated;
revoke all on function public.clinic_booking_command(text,jsonb,uuid),public.clinic_booking_shift(text,jsonb,uuid),public.clinic_booking_snapshot(date,date),public.clinic_finance_snapshot(date,date,integer) from public,anon;
grant execute on function public.clinic_booking_command(text,jsonb,uuid),public.clinic_booking_shift(text,jsonb,uuid),public.clinic_booking_snapshot(date,date),public.clinic_finance_snapshot(date,date,integer) to authenticated;
commit;
